def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    bottom = max(r for r, c in cells)

    out = [[0 if v == 6 else v for v in row] for row in grid]
    for r, c in cells:
        rr = 2 * bottom + 1 - r
        if 0 <= rr < h:
            out[rr][c] = 4
    return out
